-- Catálogo de bebidas BR (Open Food Facts + curados)
-- Rode no SQL Editor do projeto jdkggegrreixywoyhkmb

create table if not exists public.product_catalog (
  barcode text primary key,
  sku text not null,
  name text not null,
  brand text,
  product_group text not null default 'bebida',
  quantity text,
  unit text not null default 'un',
  suggested_price numeric(12,2) not null default 0,
  suggested_cost numeric(12,2) not null default 0,
  source text,
  image_url text,
  created_at timestamptz not null default now()
);

alter table public.product_catalog enable row level security;

drop policy if exists "catalog_select_authenticated" on public.product_catalog;
create policy "catalog_select_authenticated"
  on public.product_catalog for select
  to authenticated
  using (true);

drop policy if exists "catalog_select_anon" on public.product_catalog;
create policy "catalog_select_anon"
  on public.product_catalog for select
  to anon
  using (true);

create index if not exists product_catalog_group_idx on public.product_catalog (product_group);
create index if not exists product_catalog_name_idx on public.product_catalog (name);

truncate table public.product_catalog;







